const reserveNativeRuntimeBindingCapacity = `-- name: ReserveNativeRuntimeBindingCapacity :one
UPDATE runtime_binding AS b
SET active_task_count = b.active_task_count + 1,
    updated_at = now()
WHERE b.id = $1
  AND b.workspace_id = $2
  AND b.generation = $3
  AND b.transport_binding = 'native_credential_home'
  AND b.state = 'active'
  AND b.active_task_count < b.max_concurrent_tasks
  AND EXISTS (
      SELECT 1
      FROM runtime_home_assignment a
      JOIN credential_home_catalog c ON c.id = a.catalog_id
      JOIN credential_home_catalog_entry e
        ON e.id = a.catalog_entry_id
       AND e.catalog_id = a.catalog_id
       AND e.generation = a.catalog_generation
       AND e.home_ref = a.home_ref
      WHERE a.id = $4
        AND a.binding_id = b.id
        AND a.workspace_id = b.workspace_id
        AND a.catalog_generation = $5
        AND a.state = 'active'
        AND c.generation = $5
        AND c.state = 'available'
        AND e.approved = true
        AND e.state = 'healthy'
        AND e.health_watermark >= $6
        AND e.retention_deadline > now()
  )
RETURNING b.id, b.enrollment_id, b.session_id, b.workspace_id, b.runtime_id, b.agent_id, b.transport_binding, b.generation, b.max_concurrent_tasks, b.active_task_count, b.state, b.created_by, b.created_at, b.updated_at, b.deactivated_at, b.active_configuration_version_id, b.effective_configuration_digest
`

